const $ = s => document.querySelector(s);
const state = { user:null, csrf:null, refs:null, settings:null, view:'today', appointments:[], encounters:[], followups:[], materials:[] };
const roleNames = {manager:'负责人',frontdesk:'前台',cashier:'收费人员',dentist:'牙医',assistant:'诊疗助理'};
const statusNames = {pending:'待处理',confirmed:'已预约',arrived:'已到诊',waiting:'候诊中',in_treatment:'诊疗中',completed:'已完成',cancelled:'已取消',rescheduled:'已改期',no_show:'未到诊',draft:'草稿',signed:'已签署',amended:'已更正',paid:'已支付',partially_paid:'部分支付',partially_refunded:'部分退款',refunded:'已退款',agreed:'已同意',partially_agreed:'部分同意',rejected:'已拒绝',pending_decision:'待患者决定',closed:'已关闭'};
const esc = v => String(v ?? '').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const money = v => `¥${Number(v||0).toFixed(2)}`;
const displayDate = d => new Date(typeof d==='string'&&/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(?:\.\d+)?$/.test(d)?d.replace(' ','T')+'Z':d);
const localDate = d => { const x=displayDate(d); return Number.isNaN(x.getTime())?'':x.toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit',weekday:'short'}); };
const localTime = d => { const x=displayDate(d); return Number.isNaN(x.getTime())?'':x.toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}); };
const isoDay = d => {const x=d?new Date(d):new Date();return new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,10)};
function has(...roles){return roles.some(r=>state.user?.roles.includes(r));}
function flash(message,type='ok'){const el=$('#flash');el.textContent=message;el.className=`flash ${type==='error'?'error':''}`;el.hidden=false;clearTimeout(flash.timer);flash.timer=setTimeout(()=>el.hidden=true,3500);}
async function api(url,options={}){
  const res=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(state.csrf?{'X-CSRF-Token':state.csrf}:{}),...(options.headers||{})},...options});
  const data=await res.json().catch(()=>({error:'服务器返回了无法读取的结果'}));
  if(res.status===401){showLogin();throw new Error(data.error||'请重新登录');}
  if(!res.ok){const e=new Error(data.error||'操作失败');e.data=data;throw e;}return data;
}
function showLogin(){state.user=null;$('#app-shell').hidden=true;$('#login-screen').hidden=false;}
function showApp(){
  $('#login-screen').hidden=true;$('#app-shell').hidden=false;$('#user-name').textContent=state.user.name;$('#user-roles').textContent=state.user.roles.map(r=>roleNames[r]||r).join('、');
  $('#mobile-user').textContent=`${state.user.name} · ${state.user.roles.map(r=>roleNames[r]||r).join('、')}`;
  document.querySelectorAll('[data-role]').forEach(el=>{el.hidden=!el.dataset.role.split(',').some(r=>state.user.roles.includes(r));});
}
function modal(title,html,onReady){const dialog=$('#modal');$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;if(!dialog.open)dialog.showModal();onReady?.($('#modal-content'));}
function closeModal(){ $('#modal').close(); }
function formData(form){form.dataset.requestId ||= crypto.randomUUID();return {...Object.fromEntries(new FormData(form).entries()),requestId:form.dataset.requestId};}
function setHeader(kicker,title,actions=''){ $('#view-kicker').textContent=kicker;$('#view-title').textContent=title;$('#view-actions').innerHTML=actions; }
function empty(title,copy){return `<div class="empty"><strong>${esc(title)}</strong>${esc(copy)}</div>`;}
function status(s){return `<span class="status ${esc(s)}">${esc(statusNames[s]||s)}</span>`;}
function followStatus(s){const names={pending:'待联系',contacted:'已联系待评估',scheduled:'已约复诊',completed:'评估完成',cancelled:'已取消'};return `<span class="status ${esc(s)}">${esc(names[s]||statusNames[s]||s)}</span>`;}
function invoiceStatus(s){const names={pending:'待支付',partially_paid:'部分支付',paid:'已支付',partially_refunded:'部分退款',refunded:'已退款'};return `<span class="status ${esc(s)}">${esc(names[s]||statusNames[s]||s)}</span>`;}
function exportDialog(type,title){const end=isoDay();const startDate=new Date();startDate.setDate(startDate.getDate()-30);const start=isoDay(startDate);modal(`导出${title}`,`<form><div class="form-grid"><label>开始日期<input name="from" type="date" value="${start}" required></label><label>结束日期<input name="to" type="date" value="${end}" required></label></div><p class="subtext">导出文件为 UTF-8 CSV，可直接使用 Excel 打开。单次最多导出366天。</p><div class="form-actions"><button class="primary">下载 CSV</button></div></form>`,root=>root.querySelector('form').onsubmit=e=>{e.preventDefault();const b=formData(e.target);if(b.to<b.from){flash('结束日期不能早于开始日期','error');return;}closeModal();location.assign(`/api/exports?type=${encodeURIComponent(type)}&from=${encodeURIComponent(b.from)}&to=${encodeURIComponent(b.to)}`);flash('正在生成导出文件');});}

$('#login-form').addEventListener('submit',async e=>{e.preventDefault();$('#login-error').textContent='';try{const b=formData(e.target);const d=await api('/api/login',{method:'POST',body:JSON.stringify(b)});state.user=d.user;state.csrf=d.csrf;state.refs=await api('/api/reference');showApp();navigate(defaultView());}catch(err){$('#login-error').textContent=err.message;}});
async function logout(){try{await api('/api/logout',{method:'POST',body:'{}'});}finally{state.csrf=null;state.refs=null;state.settings=null;state.activePatient=null;state.activeEncounter=null;showLogin();}}
$('#logout-btn').addEventListener('click',logout);
$('#mobile-logout-btn').addEventListener('click',logout);
$('#main-nav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(b)navigate(b.dataset.view);});
async function navigate(view){
  const roles=VIEW_ROLES[view];
  if(!roles||!has(...roles)){flash('当前岗位不能办理该项业务','error');return;}
  state.view=view;document.querySelectorAll('#main-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
  $('#content').innerHTML='<div class="empty">正在读取…</div>';setHeader('','读取中');
  try{if(!state.refs)state.refs=await api('/api/reference');await ({today,patients,appointments,clinical,billing,followups,prices,materials,reconciliations,reports,settings}[view])();}
  catch(e){$('#content').innerHTML=empty('无法打开页面',e.message);flash(e.message,'error');}
}

async function today(){
  const d=await api('/api/dashboard');setHeader(localDate(d.day),'今日接待',`${has('frontdesk')?'<button class="primary" onclick="app.newAppointment()">新增预约</button>':''}`);
  state.appointments=d.appointments;const rows=d.appointments.map(a=>`<tr><td><strong>${localTime(a.start_at)}</strong><span class="subtext">${localTime(a.end_at)}</span></td><td><span class="patient-name">${esc(a.full_name)}</span><span class="subtext">${esc(a.patient_no)} · ${esc(a.phone||'无电话')}</span>${a.alerts?`<span class="subtext risk">⚠ ${esc(a.alerts)}</span>`:''}</td><td>${esc(a.dentist_name)}<span class="subtext">${esc(a.chair_name)}</span></td><td>${esc(a.service_name||'未指定')}</td><td>${status(a.status)}</td><td class="row-actions">${nextActions(a)}</td></tr>`).join('');
  const roleMetric=has('cashier','frontdesk','manager')
    ? `<div class="metric ${d.unpaid>0?'alert':''}"><strong>${money(d.unpaid)}</strong><span>未结余额</span></div>`
    : `<div class="metric"><strong>${d.counts.confirmed||0}</strong><span>待到诊</span></div>`;
  $('#content').innerHTML=`<div class="metrics"><div class="metric"><strong>${d.appointments.length}</strong><span>今日预约</span></div><div class="metric"><strong>${d.counts.arrived||0}</strong><span>已到诊</span></div><div class="metric"><strong>${d.followups}</strong><span>待处理复诊</span></div>${roleMetric}</div><div class="section-head"><h2>今日时间线</h2><p>前台核对到诊，接诊牙医处理诊疗</p></div>${rows?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>患者</th><th>资源</th><th>项目</th><th>状态</th><th>下一步</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('今天还没有预约','新增预约后会显示在这里。')}`;
}
function nextActions(a){
  const list=[];
  if(has('frontdesk')&&a.status==='confirmed'){
    list.push(`<button class="secondary" onclick="app.apptStatus(${a.id},'arrived')">登记到诊</button>`);
    list.push(`<button class="ghost" onclick="app.editAppointment(${a.id})">调整安排</button>`);
    list.push(`<button class="ghost" onclick="app.apptStatus(${a.id},'cancelled',true)">取消预约</button>`);
  }
  if(a.status==='arrived'&&has('dentist'))list.push(`<button class="primary" onclick="app.openAppointmentEncounter(${a.id})">打开诊疗记录</button>`);
  return list.join('');
}

async function patients(){
  setHeader('统一患者编号','患者档案',`${has('frontdesk')?'<button class="secondary" onclick="app.exportDialog(\'patients\',\'患者档案\')">导出</button><button class="primary" onclick="app.newPatient()">新建患者</button>':''}`);const d=await api('/api/patients');
  $('#content').innerHTML=`<div class="searchbar"><input id="patient-q" placeholder="输入患者编号、姓名或手机号"><button class="secondary" onclick="app.searchPatients()">检索</button></div><div id="patient-results">${patientTable(d.patients)}</div>`;
}
function patientTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>患者</th><th>联系方式</th><th>风险提示</th><th>建立时间</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><span class="patient-name">${esc(p.full_name)}</span><span class="subtext">${esc(p.patient_no)} · ${esc(p.sex||'未填')} · ${esc(p.birth_date||'生日未填')}</span></td><td>${esc(p.phone||'—')}<span class="subtext">偏好：${esc(p.contact_preference)}</span></td><td class="${p.alerts?'risk':''}">${esc(p.alerts||'无')}</td><td>${localDate(p.created_at)}</td><td><button class="ghost" onclick="app.patientDetail(${p.id})">打开档案</button></td></tr>`).join('')}</tbody></table></div>`:empty('没有匹配患者','可以调整检索条件或建立新档案。');}
async function searchPatients(){const d=await api(`/api/patients?q=${encodeURIComponent($('#patient-q').value)}`);$('#patient-results').innerHTML=patientTable(d.patients);}
function patientForm(p={}){return `<form id="patient-form"><div class="form-grid"><label>姓名 *<input name="fullName" value="${esc(p.full_name||'')}" required></label><label>联系电话 *<input name="phone" value="${esc(p.phone||'')}" required></label><label>性别<select name="sex"><option value="">未填写</option><option ${p.sex==='男'?'selected':''}>男</option><option ${p.sex==='女'?'selected':''}>女</option><option ${p.sex==='其他'?'selected':''}>其他</option></select></label><label>出生日期<input name="birthDate" type="date" value="${esc(p.birth_date||'')}"></label><label>紧急联系人<input name="emergencyContact" value="${esc(p.emergency_contact||'')}"></label><label>联系偏好<select name="contactPreference">${['电话','微信','短信'].map(v=>`<option ${v===(p.contact_preference||'电话')?'selected':''}>${v}</option>`).join('')}</select></label>${p.id?`<label class="full">变更原因 *<textarea name="reason" required></textarea></label>`:`<label class="full">健康风险提示<input name="alert" placeholder="例如：青霉素过敏"></label>`}<label class="full">备注<textarea name="notes">${esc(p.notes||'')}</textarea></label></div><div class="form-actions"><button class="ghost" type="button" onclick="app.closeModal()">取消</button><button class="primary">保存患者</button></div></form>`;}
function newPatient(){modal('新建患者',patientForm(),root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();let b=formData(e.target);try{await api('/api/patients',{method:'POST',body:JSON.stringify(b)});closeModal();flash('患者档案已建立');navigate('patients');}catch(err){if(err.data?.duplicates&&confirm(`${err.message}\n仍要建立新档案吗？`)){b.confirmDuplicate=true;await api('/api/patients',{method:'POST',body:JSON.stringify(b)});closeModal();navigate('patients');}else flash(err.message,'error');}});}
function editPatient(id){const p=state.activePatient;if(!p||p.id!==id)return;modal('修改患者资料',patientForm(p),root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);b.expectedVersion=p.version;try{await api(`/api/patients/${id}`,{method:'PUT',body:JSON.stringify(b)});flash('资料和变更依据已保存');if(state.view==='patients')await searchPatients();await patientDetail(id);}catch(err){if(err.data?.duplicates&&confirm(`${err.message}，已核对为不同患者吗？`)){b.confirmDuplicate=true;try{await api(`/api/patients/${id}`,{method:'PUT',body:JSON.stringify(b)});if(state.view==='patients')await searchPatients();await patientDetail(id);}catch(e){flash(e.message,'error');}}else flash(err.message,'error');}});}

async function patientDetail(id){
  const {patient:p}=await api(`/api/patients/${id}`);state.activePatient=p;const context=(p.encounters||[]).find(e=>Number(e.dentist_id)===Number(state.user.id));const canReadClinical=has('dentist')&&!!context;
  modal(`${p.full_name} · ${p.patient_no}`,`<div class="split"><div><div class="panel"><h3>基本资料</h3>${has('frontdesk')?`<button class="secondary" onclick="app.editPatient(${p.id})">修改资料</button>`:''}<p>${esc(p.phone||'无电话')}<br>${esc(p.birth_date||'生日未填')} · ${esc(p.sex||'性别未填')}<br>紧急联系人：${esc(p.emergency_contact||'—')}</p><h3>健康风险</h3>${(p.alerts||[]).length?p.alerts.map(a=>`<p class="risk">${esc(a.description)}</p>`).join(''):'<p>无已知提示</p>'}</div></div><div><div class="panel"><h3>最近预约</h3>${(p.appointments||[]).slice(0,6).map(a=>`<p><strong>${localDate(a.start_at)} ${localTime(a.start_at)}</strong> ${status(a.status)}</p>`).join('')||'<p>暂无</p>'}<h3>最近就诊</h3>${(p.encounters||[]).slice(0,5).map(e=>canReadClinical?`<p><button class="ghost" onclick="app.encounterDetail(${e.id},${context?.id||0})">${esc(e.encounter_no)} · ${localDate(e.started_at)}</button></p>`:`<p>${esc(e.encounter_no)} · ${localDate(e.started_at)}</p>`).join('')||'<p>暂无</p>'}</div></div></div>${(p.changes||[]).length?`<div class="panel"><h3>资料变更历史</h3>${p.changes.map(c=>{const old=JSON.parse(c.old_json),next=JSON.parse(c.new_json);return `<p>${timeStamp(c.changed_at)} · ${esc(c.changed_name)} · ${esc(c.reason)}<br>姓名：${esc(old.full_name)} → ${esc(next.full_name)}；电话：${esc(old.phone)} → ${esc(next.phone)}</p>`;}).join('')}</div>`:''}`);
}

async function appointments(){
  if(!has('frontdesk')){setHeader('查询本人已确认的接诊时段','可用接诊安排','<button class="primary" onclick="app.availabilityDialog()">查询可用时段</button>');$('#content').innerHTML=empty('按牙椅、日期与时长查询','查询不创建预约；预约由前台依据确认安排办理。');return;}
  setHeader('按已确认接诊时段安排','预约日程',`<button class="secondary" onclick="app.availabilityDialog()">查询可用时段</button>${has('frontdesk')?'<button class="primary" onclick="app.newAppointment()">新增预约</button>':''}`);
  const day=state.appointmentDay||isoDay();const d=await api(`/api/appointments?from=${day}&to=${day}&q=${encodeURIComponent(state.appointmentQuery||'')}`);state.appointments=d.appointments;
  $('#content').innerHTML=`<div class="inline-form"><div class="form-grid"><label>查看日期<input id="appt-day" type="date" value="${day}" onchange="app.loadAppointments(this.value)"></label><label>患者姓名或联系电话<input id="appointment-query" value="${esc(state.appointmentQuery||'')}" placeholder="姓名、电话或患者编号"></label></div><button class="secondary" onclick="app.searchAppointments()">检索预约</button></div><div id="appt-list">${appointmentTable(d.appointments)}</div>`;
}
function availabilityDialog(){const dentists=state.refs.users.filter(u=>String(u.roles).split(',').includes('dentist')&&(has('frontdesk')||Number(u.id)===Number(state.user.id)));modal('查询可用接诊时段',`<form><div class="form-grid"><label>接诊牙医<select name="dentistId">${dentists.map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('')}</select></label><label>牙椅<select name="chairId">${state.refs.chairs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>日期<input name="date" type="date" value="${isoDay()}" required></label><label>所需分钟<input name="duration" type="number" min="10" max="480" step="1" value="30" required></label></div><button class="primary">查询</button><div id="slot-result"></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);delete b.requestId;try{const d=await api(`/api/availability?${new URLSearchParams(b)}`);root.querySelector('#slot-result').innerHTML=`<div class="panel"><h3>可用时段</h3>${d.slots.length?d.slots.map(s=>`<p>${esc(s.label)}</p>`).join(''):`<p>${esc(d.reason||'没有可用时段')}</p>`}</div>`;}catch(e){flash(e.message,'error');}});}

function searchAppointments(){state.appointmentQuery=$('#appointment-query').value;loadAppointments(state.appointmentDay||isoDay());}

function appointmentTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>时间</th><th>患者</th><th>牙医／牙椅</th><th>项目</th><th>状态</th><th></th></tr></thead><tbody>${rows.map(a=>`<tr><td>${localDate(a.start_at)}<br><strong>${localTime(a.start_at)}–${localTime(a.end_at)}</strong></td><td>${esc(a.full_name)}<span class="subtext">${esc(a.patient_no)}</span></td><td>${esc(a.dentist_name)}<span class="subtext">${esc(a.chair_name)}</span></td><td>${esc(a.service_name||'未指定')}</td><td>${status(a.status)}</td><td class="row-actions">${nextActions(a)}</td></tr>`).join('')}</tbody></table></div>`:empty('这一天没有预约','选择其他日期或新增预约。');}
async function loadAppointments(day){try{state.appointmentDay=day;const d=await api(`/api/appointments?from=${day}&to=${day}&q=${encodeURIComponent(state.appointmentQuery||'')}`);state.appointments=d.appointments;$('#appt-list').innerHTML=appointmentTable(d.appointments);}catch(e){flash(e.message,'error');}}
async function newAppointment(){if(!has('frontdesk'))return;await appointmentDialog();}
async function apptStatus(id,next,needReason=false){
  if(!has('frontdesk'))return;let reason='';if(needReason){reason=prompt('请填写取消原因：')||'';if(!reason.trim())return;}
  const a=state.appointments.find(x=>x.id===id);try{const d=await api(`/api/appointments/${id}/status`,{method:'POST',body:JSON.stringify({status:next,reason,expectedVersion:a?.version})});
    flash(next==='arrived'?`到诊登记完成${d.encounter?.encounter_no?'，本次就诊 '+d.encounter.encounter_no:''}`:'预约已取消');await navigate(state.view);
  }catch(e){flash(e.message,'error');await navigate(state.view);}
}

async function clinical(){setHeader('检查、方案和实际诊疗记录','临床诊疗');const d=await api('/api/encounters');state.encounters=d.encounters;
  $('#content').innerHTML=d.encounters.length?`<div class="table-wrap"><table><thead><tr><th>就诊</th><th>患者</th><th>接诊牙医</th><th>诊断／牙位</th><th>记录状态</th><th></th></tr></thead><tbody>${d.encounters.map(e=>`<tr><td><strong>${esc(e.encounter_no)}</strong><span class="subtext">${localDate(e.started_at)} ${localTime(e.started_at)}</span></td><td>${esc(e.full_name)}<span class="subtext">${esc(e.patient_no)}</span></td><td>${esc(e.dentist_name)}</td><td>${esc(e.diagnosis||'尚未填写')}<span class="subtext">${esc(e.findings||'')}</span></td><td>${status(e.status)}</td><td><button class="ghost" onclick="app.encounterDetail(${e.id})">打开诊疗</button></td></tr>`).join('')}</tbody></table></div>`:empty('还没有就诊记录','前台登记到诊后生成本次就诊记录。');
}
async function openAppointmentEncounter(apptId){try{const d=await api('/api/encounters');const e=d.encounters.find(x=>Number(x.appointment_id)===Number(apptId));if(!e)throw new Error('未找到本次到诊的就诊记录，请由前台核对到诊登记。');await encounterDetail(e.id);}catch(e){flash(e.message,'error');}}
const attachmentCategoryNames={xray:'牙片',photo:'口内照片',consent:'知情同意材料',report:'检查报告',other:'其他'};
function attachmentSection(e){const items=(e.attachments||[]).map(a=>`<article><strong>${esc(attachmentCategoryNames[a.category]||a.category)} · ${esc(a.original_name)}</strong><p>${esc(a.description||'无说明')}</p><small>${(a.file_size/1024).toFixed(1)}KB · ${esc(a.uploaded_name)} · ${localDate(a.created_at)} ${localTime(a.created_at)}</small><div class="row-actions"><button class="secondary" onclick="app.openAttachment(${a.id})">查看附件</button>${has('manager')?`<button class="ghost" onclick="app.archiveAttachment(${a.id},${e.id})">归档</button>`:''}</div></article>`).join('');return `<div class="panel"><div class="section-head"><div><h3>病历附件与牙片</h3><p>仅临床角色可查看，单个文件不超过2MB</p></div>${Number(e.dentist_id)===Number(state.user.id)?`<button class="secondary" onclick="app.uploadAttachment(${e.id},${e.patient_id})">上传附件</button>`:''}</div>${items?`<div class="timeline">${items}</div>`:'<p class="subtext">还没有附件。</p>'}</div>`;}
function fileAsBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file);});}
function uploadAttachment(encounterId,patientId){modal('上传病历附件',`<form><div class="form-grid"><label>分类<select name="category"><option value="xray">牙片</option><option value="photo">口内照片</option><option value="consent">知情同意材料</option><option value="report">检查报告</option><option value="other">其他</option></select></label><label>文件<input name="file" type="file" accept="image/jpeg,image/png,application/pdf" required></label><label class="full">说明<input name="description" placeholder="例如：治疗前根尖片，右下46牙"></label></div><div class="form-actions"><button class="primary">上传并关联病历</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const form=ev.target;const file=form.querySelector('[name=file]').files[0];if(!file)return;if(file.size>2*1024*1024){flash('单个附件不能超过2MB','error');return;}const b=formData(form);delete b.file;try{b.patientId=patientId;b.encounterId=encounterId;b.filename=file.name;b.mimeType=file.type;b.dataBase64=await fileAsBase64(file);await api('/api/attachments',{method:'POST',body:JSON.stringify(b)});closeModal();flash('附件已上传并关联病历');encounterDetail(encounterId);}catch(err){flash(err.message,'error');}});}
function openAttachment(id){window.open(`/api/attachments/${id}/file?currentEncounterId=${state.clinicalContext||0}`,'_blank','noopener');}
async function archiveAttachment(id,encounterId){const reason=prompt('请填写归档原因：')||'';if(!reason)return;try{await api(`/api/attachments/${id}/archive`,{method:'PUT',body:JSON.stringify({reason})});flash('附件已归档并保留审计记录');encounterDetail(encounterId);}catch(err){flash(err.message,'error');}}
async function encounterDetail(id,currentEncounterId=0){
  const {encounter:e}=await api(`/api/encounters/${id}?currentEncounterId=${currentEncounterId}`);state.clinicalContext=currentEncounterId;state.activeEncounter=e;
  const canTreat=has('dentist')&&Number(e.dentist_id)===Number(state.user.id);const signed=['signed','amended'].includes(e.status);const readonly=!canTreat||signed;
  const findings=(e.findings||[]).map(x=>`${x.tooth_code}:${x.finding}`).join('\n');
  const clinicalForm=`<form id="enc-form"><div class="form-grid"><label class="full">主诉 *<textarea name="chiefComplaint" ${readonly?'readonly':''}>${esc(e.chief_complaint||'')}</textarea></label><label class="full">相关病史<textarea name="relevantHistory" ${readonly?'readonly':''}>${esc(e.relevant_history||'')}</textarea></label><label class="full">牙位检查（每行“牙位:检查所见”）<textarea name="findings" ${readonly?'readonly':''}>${esc(findings)}</textarea></label><label class="full">诊断 *<textarea name="diagnosis" ${readonly?'readonly':''}>${esc(e.diagnosis||'')}</textarea></label><label class="full">治疗经过<textarea name="clinicalNotes" ${readonly?'readonly':''}>${esc(e.clinical_notes||'')}</textarea></label><label class="full">诊后指导 *<textarea name="instructions" ${readonly?'readonly':''}>${esc(e.instructions||'')}</textarea></label></div>${readonly?'':`<div class="form-actions"><button class="secondary" type="button" onclick="app.addPlan(${e.id})">治疗方案与患者决定</button><button class="secondary" type="button" onclick="app.addTreatment(${e.id})">确认实际项目</button><button class="ghost" type="submit">保存诊疗记录</button><button class="primary" type="button" onclick="app.signEncounter(${e.id})">确认本次病历</button></div>`}</form>`;
  const plans=(e.plans||[]).map(x=>`<article><strong>${esc(x.plan_no||'方案')} · ${status(x.status)}</strong><p>${esc(x.summary||'')}</p>${canTreat&&!signed?`<button class="secondary" onclick="app.planDecision(${x.id},${e.id})">记录患者决定</button>`:''}</article>`).join('');
  modal(`${e.full_name} · ${e.encounter_no}`,`<div class="panel"><p>${status(e.status)} · 接诊牙医：${esc(e.dentist_name)}</p>${(e.alerts||[]).length?`<p class="risk">${e.alerts.map(a=>esc(a.description)).join('；')}</p>`:''}${!canTreat?'<p class="subtext">诊疗内容由本次接诊牙医确认。</p>':''}</div>${clinicalForm}${plans?`<div class="panel"><h3>已记录方案</h3>${plans}</div>`:''}${attachmentSection(e)}${signed&&canTreat?`<div class="form-actions"><button class="secondary" onclick="app.amendEncounter(${e.id})">追加病历补充</button></div>`:''}${canTreat&&(e.treatments||[]).length?`<div class="form-actions"><button class="secondary" onclick="app.correctProjects(${e.id})">更正实际项目</button></div>`:''}${(e.treatments||[]).length?`<div class="panel"><h3>实际完成项目</h3>${e.treatments.map(t=>`<p>${esc(t.tooth_code||'全口')} · ${esc(t.service_name)} × ${esc(t.quantity)} ${esc(t.unit||'')} · ${t.price_missing||t.unit_price_snapshot==null?'待补齐适用价目':money(t.unit_price_snapshot)}</p>`).join('')}</div>`:''}${(e.amendments||[]).length?`<div class="panel"><h3>病历补充历史</h3><div class="timeline">${e.amendments.map(a=>`<article><strong>${esc(a.signed_name)} · ${localDate(a.signed_at)}</strong><p>${esc(a.amendment_text)}</p><small>原因：${esc(a.reason)}</small></article>`).join('')}</div></div>`:''}`,root=>{
    const f=root.querySelector('#enc-form');if(!readonly)f.onsubmit=async ev=>{ev.preventDefault();try{await saveClinicalDraft(id);flash('诊疗记录已保存');}catch(err){flash(err.message,'error');}};
  });
}
async function signEncounter(id){try{await saveClinicalDraft(id);await api(`/api/encounters/${id}/sign`,{method:'POST',body:JSON.stringify({expectedVersion:state.activeEncounter.version})});flash('病历已签署');encounterDetail(id);}catch(e){flash(e.message,'error');}}
function amendEncounter(id){const text=prompt('补充更正内容：');if(!text)return;const reason=prompt('更正原因：');if(!reason)return;api(`/api/encounters/${id}/amend`,{method:'POST',body:JSON.stringify({text,reason})}).then(()=>{flash('补充更正已签署');encounterDetail(id)}).catch(e=>flash(e.message,'error'));}
async function addPlan(encounterId){try{await saveClinicalDraft(encounterId);}catch(err){flash(err.message,'error');return;}modal('建立治疗方案',`<form id="plan-form"><div class="form-grid"><label class="full">方案说明<textarea name="summary"></textarea></label><label>治疗项目<select name="serviceId">${state.refs.services.map(s=>`<option value="${s.id}" data-price="${s.current_price}">${esc(s.name)} · ${money(s.current_price)}</option>`).join('')}</select></label><label>牙位<input name="toothCode" placeholder="例如 11"></label><label>计划次数<input name="quantity" type="number" min="1" value="1"></label><label>患者决定<select name="decision"><option value="agreed">同意</option><option value="pending">待考虑</option><option value="rejected">拒绝</option><option value="deferred">暂缓</option></select></label></div><div class="form-actions"><button class="primary">保存方案</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);const s=state.refs.services.find(x=>x.id===Number(b.serviceId));try{const d=await api(`/api/encounters/${encounterId}/plans`,{method:'POST',body:JSON.stringify({expectedVersion:state.activeEncounter.version,summary:b.summary,items:[{serviceId:b.serviceId,toothCode:b.toothCode,quantity:b.quantity,estimatedPrice:s.current_price,decision:b.decision}]})});closeModal();flash('治疗方案已保存');encounterDetail(encounterId);}catch(err){flash(err.message,'error');}});}
async function planDecision(id,encounterId){try{await saveClinicalDraft(encounterId);}catch(e){flash(e.message,'error');return;}const {plan}=await api(`/api/plans/${id}`);modal('记录患者对方案的决定',`<form>${plan.items.map(i=>`<label>${esc(i.service_name)} · ${esc(i.tooth_code||'全口')}<select name="item-${i.id}">${[['pending','待考虑'],['agreed','同意'],['rejected','拒绝'],['deferred','暂缓']].map(([v,n])=>`<option value="${v}" ${v===i.decision?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<div class="form-actions"><button class="primary">保存患者决定</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await api(`/api/plans/${id}/decision`,{method:'POST',body:JSON.stringify({expectedVersion:plan.clinicalVersion,items:plan.items.map(i=>({id:i.id,decision:ev.target.elements[`item-${i.id}`].value}))})});await encounterDetail(encounterId);flash('患者决定已保存');}catch(e){flash(e.message,'error');}});}

async function saveClinicalDraft(id){
 const f=$('#enc-form');if(!f||!state.activeEncounter||Number(state.activeEncounter.id)!==Number(id)||state.activeEncounter.status!=='draft')return;
 const b=formData(f),lines=String(b.findings||'').split('\n').filter(x=>x.trim());
 b.findings=lines.map(x=>{const i=x.indexOf(':');if(i<1||!x.slice(i+1).trim())throw new Error('每条检查须填写牙位和检查所见');return {toothCode:x.slice(0,i).trim(),finding:x.slice(i+1).trim()};});
 b.expectedVersion=state.activeEncounter.version;
 const saved=await api(`/api/encounters/${id}`,{method:'PUT',body:JSON.stringify(b)});state.activeEncounter.version=saved.version;
}
async function addTreatment(encounterId){
 try{await saveClinicalDraft(encounterId);}catch(err){flash(err.message,'error');return;}
 const e=state.activeEncounter;let agreed=[];
 for(const plan of e.plans||[]){const d=await api(`/api/plans/${plan.id}`);agreed.push(...d.plan.items.filter(i=>i.decision==='agreed'&&i.planned_quantity>i.completed_quantity));}
 modal('确认实际完成项目',`<form><div class="form-grid"><label class="full">方案依据<select name="planItemId"><option value="">方案外实际项目</option>${agreed.map(i=>`<option value="${i.id}">${esc(i.service_name)} · ${esc(i.tooth_code||'全口')} · 余 ${i.planned_quantity-i.completed_quantity}</option>`).join('')}</select></label><label>实际项目<select name="serviceId">${state.refs.services.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><label>牙位<input name="toothCode"></label><label>数量<input name="quantity" type="number" min="1" step="1" value="1" required></label><label class="full">方案外项目原因<input name="outsidePlanReason"></label><label class="check-row full"><input name="patientConfirmed" type="checkbox">患者已确认方案外处置及费用说明</label><label class="full">实际诊疗结果<textarea name="outcome"></textarea></label></div><div class="form-actions"><button class="primary">确认实际项目</button></div></form>`,root=>{
  const f=root.querySelector('form'),select=f.querySelector('[name=planItemId]');
  function choose(){const i=agreed.find(i=>Number(i.id)===Number(select.value));if(i){f.querySelector('[name=serviceId]').value=i.service_id;f.querySelector('[name=toothCode]').value=i.tooth_code||'';f.querySelector('[name=quantity]').max=i.planned_quantity-i.completed_quantity;}else f.querySelector('[name=quantity]').removeAttribute('max');f.querySelector('[name=outsidePlanReason]').required=!i;f.querySelector('[name=patientConfirmed]').required=!i;}
  select.onchange=choose;if(agreed.length)select.value=agreed[0].id;choose();
  f.onsubmit=async ev=>{ev.preventDefault();const b=formData(f);b.expectedVersion=e.confirmation_version;b.patientConfirmed=f.querySelector('[name=patientConfirmed]').checked;if(!b.planItemId)delete b.planItemId;try{await api(`/api/encounters/${encounterId}/treatments`,{method:'POST',body:JSON.stringify(b)});await encounterDetail(encounterId);flash('实际项目已确认，价格按适用价目确定');}catch(err){flash(err.message,'error');}};
 });
}
function correctProjects(id){
 const e=state.activeEncounter;if(!e||Number(e.id)!==Number(id))return;
 modal('更正实际完成项目',`<form><p>仅填写本次实际完成项目。更正须留原因；已结清项目无法覆盖。</p>${e.treatments.map((t,i)=>`<div class="form-grid project-row"><label>保留项目<input name="keep_${i}" type="checkbox" checked></label><label>方案依据<select name="plan_${i}"><option value="">方案外项目</option>${t.plan_item_id?`<option value="${t.plan_item_id}" selected>原同意方案项目 ${t.plan_item_id}</option>`:''}</select></label><label>项目<select name="service_${i}">${state.refs.services.map(s=>`<option value="${s.id}" ${Number(s.id)===Number(t.service_id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>牙位<input name="tooth_${i}" value="${esc(t.tooth_code||'')}"></label><label>实际数量<input name="quantity_${i}" type="number" min="1" step="1" value="${t.quantity}" required></label></div>`).join('')}<label>更正原因<textarea name="reason" required></textarea></label><label>方案外更正原因<textarea name="outsidePlanReason"></textarea></label><label class="check-row"><input name="patientConfirmed" type="checkbox">患者已确认方案外更正及费用说明</label><div class="form-actions"><button class="primary">核实并保存新项目版本</button></div></form>`,root=>{root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=ev.target;const items=e.treatments.map((t,i)=>f.querySelector(`[name=keep_${i}]`).checked?{treatmentId:t.id,planItemId:f.querySelector(`[name=plan_${i}]`).value||null,serviceId:Number(f.querySelector(`[name=service_${i}]`).value),toothCode:f.querySelector(`[name=tooth_${i}]`).value,quantity:Number(f.querySelector(`[name=quantity_${i}]`).value)}:null).filter(Boolean);try{await api(`/api/encounters/${id}/treatment-confirmation`,{method:'PUT',body:JSON.stringify({expectedVersion:e.confirmation_version,reason:f.querySelector('[name=reason]').value,outsidePlanReason:f.querySelector('[name=outsidePlanReason]').value,patientConfirmed:f.querySelector('[name=patientConfirmed]').checked,items})});await encounterDetail(id);flash('新项目版本已保存，请收费人员重新核对费用');}catch(err){flash(err.message,'error');}};});
}
function endPrice(id){const v=(state.priceVersions||[]).find(v=>Number(v.id)===Number(id));if(!v||!has('cashier'))return;modal('结束价目适用区间',`<form><div class="form-grid"><label>适用结束<input name="effectiveTo" type="datetime-local" required></label><label>确认负责人<select name="confirmedBy">${managerOptions()}</select></label><label>负责人确认时间<input name="confirmedAt" type="datetime-local" value="${localInput()}" required></label><label class="full">确认内容与原因<textarea name="confirmationNote" required></textarea></label></div><div class="form-actions"><button class="primary">保存已确认的结束时间</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);b.expectedVersion=v.version;b.confirmedAt=new Date(b.confirmedAt).toISOString();b.effectiveTo=new Date(b.effectiveTo).toISOString();try{await api(`/api/price-versions/${id}/end`,{method:'PUT',body:JSON.stringify(b)});closeModal();await loadPrices(v.service_id);}catch(err){flash(err.message,'error');}});}

async function billing(){
  setHeader('确认项目、核对金额、现金足额结清','收费结算');const [d,pending]=await Promise.all([api('/api/invoices'),api('/api/billing/pending')]);
  const waiting=(pending.pending||[]).length?`<div class="section-head"><h2>待结算诊疗</h2></div><div class="table-wrap"><table><thead><tr><th>就诊</th><th>患者</th><th>已确认项目数</th><th class="amount">应收金额</th><th></th></tr></thead><tbody>${pending.pending.map(x=>`<tr><td>${esc(x.encounter_no)}<span class="subtext">${localDate(x.started_at)}</span></td><td>${esc(x.full_name)}<span class="subtext">${esc(x.patient_no)}</span></td><td>${x.treatment_count}</td><td class="amount">${money(x.amount)}</td><td>${has('cashier')?`<button class="primary" onclick="app.createInvoice(${x.encounter_id})">核对费用</button>`:'<span class="subtext">由收费人员办理</span>'}</td></tr>`).join('')}</tbody></table></div>`:'';
  const invoices=d.invoices.length?`<div class="section-head"><h2>结算记录</h2></div><div class="table-wrap"><table><thead><tr><th>账单</th><th>患者</th><th class="amount">应收金额</th><th>结算状态</th><th></th></tr></thead><tbody>${d.invoices.map(i=>`<tr><td>${esc(i.invoice_no)}<span class="subtext">${localDate(i.created_at)}</span></td><td>${esc(i.full_name)}<span class="subtext">${esc(i.patient_no)}</span></td><td class="amount">${money(invoiceDue(i))}</td><td>${invoiceStatus(i.status)}</td><td><button class="ghost" onclick="app.invoiceDetail(${i.id})">费用明细／收据</button></td></tr>`).join('')}</tbody></table></div>`:'';
  $('#content').innerHTML=waiting||invoices?waiting+invoices:empty('没有待结算内容','接诊牙医确认实际项目后，由收费人员核对费用。');
}
async function createInvoice(encounterId){if(!has('cashier'))return;try{const d=await api('/api/invoices',{method:'POST',body:JSON.stringify({encounterId})});closeModal();await invoiceDetail(d.invoice.id);}catch(e){flash(e.message,'error');}}
async function invoiceDetail(id){
  const {invoice:i}=await api(`/api/invoices/${id}`);const due=invoiceDue(i);const receipt=i.receipt;const settled=Boolean(receipt)||i.status==='paid';const historical=!receipt&&(Number(i.paid_amount)>0||Number(i.discount_amount)>0||Number(i.credited_amount)>0||Number(i.refunded_amount)>0);
  const lineHtml=(i.lines||[]).map(l=>`<tr><td>${esc(l.service_name)}</td><td>${esc(l.quantity)} ${esc(l.unit||'')}</td><td class="amount">${money(l.unit_price??l.unit_price_snapshot)}</td><td class="amount">${money(l.line_amount)}</td></tr>`).join('');
  modal(`${i.invoice_no} · ${i.full_name}`,`<div class="panel"><h3>已确认诊疗项目</h3><div class="table-wrap"><table><thead><tr><th>项目</th><th>数量／单位</th><th class="amount">单价</th><th class="amount">金额</th></tr></thead><tbody>${lineHtml}</tbody></table></div><p>应收金额：<strong>${money(due)}</strong></p><p>${settled?'本次费用已结清。':'请先与患者核对项目及金额，再清点实际收到的现金。'}</p></div>${receipt?receiptHtml(receipt):''}${historical?'<p>既有结算记录保留原始依据，仅供核对。</p>':''}${!settled&&!historical&&has('cashier')?`<form id="pay-form" class="inline-form"><h2>登记现金收款</h2><div class="form-grid"><label>实际收到现金<input name="amount" type="number" min="${due}" step="0.01" value="${due}" required></label><label>预计找零<input id="change-preview" value="${money(0)}" readonly></label></div><div class="form-actions"><button class="primary">核对并登记结清</button></div></form>`:''}`,root=>{
    const f=root.querySelector('#pay-form');if(!f)return;f.querySelector('[name=amount]').oninput=ev=>{root.querySelector('#change-preview').value=money(Math.max(0,Number(ev.target.value)-due));};
    f.onsubmit=async ev=>{ev.preventDefault();const amount=Number(formData(f).amount);if(!Number.isFinite(amount)||amount<due){flash('实收现金不足，不能登记结清','error');return;}const button=f.querySelector('button');button.disabled=true;
      try{const d=await api(`/api/invoices/${id}/payments`,{method:'POST',body:JSON.stringify({amount,method:'cash',expectedVersion:i.version})});flash(d.replayed?'已显示原结算记录':'现金收款已登记，请交付收据和找零');await invoiceDetail(id);}
      catch(err){flash(`${err.message}；请先查看原结算结果并核实现金，再决定是否重新提交。`,'error');try{await invoiceDetail(id);}catch{button.disabled=false;}}
    };
  });
}

async function reviewApproval(id,decision){const label=decision==='approved'?'批准':'拒绝';const note=prompt(`${label}意见：`,decision==='approved'?'资料核对无误':'')||'';if(decision==='rejected'&&!note)return;try{await api(`/api/approvals/${id}/review`,{method:'POST',body:JSON.stringify({decision,note})});flash(`申请已${label}`);approvals();}catch(err){flash(err.message,'error');}}

async function followups(){
  setHeader('牙医提出要求，前台联系，牙医评估','复诊随访',has('dentist')?'<button class="primary" onclick="app.newFollowup()">登记诊后要求</button>':'');const d=await api('/api/followups');state.followups=d.followups;
  $('#content').innerHTML=d.followups.length?`<div class="table-wrap"><table><thead><tr><th>患者</th><th>诊疗来源／要求</th><th>建议／下次联系日期</th><th>处理状态</th><th></th></tr></thead><tbody>${d.followups.map(f=>`<tr><td>${esc(f.full_name)}<span class="subtext">${esc(f.patient_no)}</span></td><td>${esc(f.reason)}<span class="subtext">${esc(f.encounter_no||'关联本次就诊')} ${esc(f.result||'')}</span></td><td>${esc(f.next_contact_date||f.due_date||'由牙医确定')}</td><td>${followStatus(f.status)}</td><td><button class="ghost" onclick="app.followupDetail(${f.id})">查看与办理</button></td></tr>`).join('')}</tbody></table></div>`:empty('没有诊后联系事项','接诊牙医可以根据本次诊疗提出复诊或随访要求。');
}
async function newFollowup(){
  if(!has('dentist'))return;const d=await api('/api/encounters');const own=d.encounters.filter(e=>Number(e.dentist_id)===Number(state.user.id)&&['signed','amended'].includes(e.status));if(!own.length){flash('请先完成到诊与诊疗记录','error');return;}
  modal('登记诊后要求',`<form><div class="form-grid"><label class="full">来源就诊<select name="encounterId" required>${own.map(e=>`<option value="${e.id}" data-patient="${e.patient_id}">${esc(e.encounter_no)} · ${esc(e.full_name)}</option>`).join('')}</select></label><label>事项类型<select name="type"><option value="revisit">复诊</option><option value="followup">随访</option></select></label><label class="full">复诊／随访要求<textarea name="reason" required></textarea></label><label>建议联系日期<input name="dueDate" type="date" required></label><label>联系前台<select name="assignedTo">${state.refs.users.filter(u=>String(u.roles).split(',').includes('frontdesk')).map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('')}</select></label></div><div class="form-actions"><button class="primary">保存诊后要求</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);b.patientId=ev.target.querySelector('[name=encounterId]').selectedOptions[0].dataset.patient;try{await api('/api/followups',{method:'POST',body:JSON.stringify(b)});closeModal();flash('已保存诊疗来源与诊后要求');await navigate('followups');}catch(err){flash(err.message,'error');}});
}
async function followupDetail(id){
  const d=await api(`/api/followups/${id}`);const f=d.followup;const own=has('dentist')&&(Number(f.sourceEncounter?.dentist_id??f.dentist_id??f.created_by)===Number(state.user.id)||Number(f.revisitEncounter?.dentist_id)===Number(state.user.id));const open=!['completed','cancelled'].includes(f.status);const choices=has('frontdesk')?(await api(`/api/patients/${f.patient_id}`)).patient.appointments.filter(a=>['confirmed','arrived'].includes(a.status)&&Number(a.id)!==Number(f.sourceEncounter?.appointment_id)):[];
  const history=(f.history||[]).map(h=>`<article><strong>${esc(h.changed_name||'工作人员')} · ${esc(timeStamp(h.changed_at))}</strong>${h.contacted_at?`<small>实际联系：${timeStamp(h.contacted_at)}</small>`:''}<p>${esc(h.result||h.note||h.details||'')} ${esc(h.status||h.to_status||'')}</p></article>`).join('');
  const content=`<div class="panel"><h3>${esc(f.full_name||'患者')} · ${esc(f.reason)}</h3><p>来源就诊：${esc(f.sourceEncounter?.encounter_no||f.encounter_no||f.encounter_id||'')}<br>建议日期：${esc(f.due_date||'')}<br>当前结果：${esc(f.result||'尚未记录')}</p>${f.appointment?`<p>关联预约：${esc(f.appointment.appointment_no)} · ${localDate(f.appointment.start_at)} ${localTime(f.appointment.start_at)}</p>`:''}</div>${f.completed_at?`<div class="panel"><h3>牙医评估</h3><p>恢复情况：${esc(f.recovery||f.clinical_result||'')}<br>结论：${esc(f.conclusion||'')}<br>后续意见：${esc(f.opinion||'')}</p></div>`:''}${history?`<div class="panel"><h3>办理历史</h3><div class="timeline">${history}</div></div>`:''}`;
  let form='';if(open&&has('frontdesk'))form=`<form id="contact-form"><div class="form-grid"><label>联系结果<select name="status"><option value="contacted">已联系，待牙医处理</option><option value="pending">未联系成功／待再次联系</option><option value="scheduled">已与患者确认复诊预约</option><option value="cancelled">患者取消（须说明原因）</option></select></label><label>实际联系时间<input type="datetime-local" name="contactedAt" value="${localInput()}" required></label><label>下次联系日期<input name="nextContactDate" type="date"></label><label class="full">联系及患者反馈<textarea name="result" required></textarea></label><label class="full">同患者复诊预约<select name="appointmentId"><option value="">暂不关联预约</option>${choices.map(a=>`<option value="${a.id}" ${Number(a.id)===Number(f.appointment_id)?'selected':''}>${esc(a.appointment_no)} · ${localDate(a.start_at)} ${localTime(a.start_at)} · ${esc(a.dentist_name)}</option>`).join('')}</select></label></div><p class="subtext">需要复诊时，先在预约板块与患者确认时段，再关联该预约。</p><div class="form-actions"><button class="primary">保存联系结果</button></div></form>`;
  else if(open&&own)form=`<form id="contact-form"><div class="form-grid"><input name="status" type="hidden" value="completed"><label class="full">恢复情况<textarea name="recovery" required></textarea></label><label class="full">评估结论<textarea name="conclusion" required></textarea></label><label class="full">后续意见<textarea name="opinion" required></textarea></label><label class="full">评估结果及后续意见<textarea name="result" required></textarea></label></div><div class="form-actions"><button class="primary">保存牙医处理结果</button></div></form>`;
  modal('诊后联系与复诊',content+form,root=>{const form=root.querySelector('#contact-form');if(form)form.onsubmit=async ev=>{ev.preventDefault();const b=formData(form);b.expectedVersion=f.version;if(b.contactedAt)b.contactedAt=new Date(b.contactedAt).toISOString();if(!b.appointmentId)delete b.appointmentId;if(!b.nextContactDate)delete b.nextContactDate;if(b.status==='scheduled'&&!b.appointmentId){flash('请关联已确认的复诊预约','error');return;}try{await api(`/api/followups/${id}`,{method:'PATCH',body:JSON.stringify(b)});closeModal();flash('办理结果已保存');await navigate('followups');}catch(err){flash(err.message,'error');}};});
}


async function reports(){
 const from=state.reportFrom||isoDay(new Date(Date.now()-30*86400000)),to=state.reportTo||isoDay();
 setHeader('按实际就诊、项目完成及收款日期汇总','日常业务汇总');const d=await api(`/api/reports/summary?from=${from}&to=${to}`);
 const rows=(d.treatments||[]).map(t=>`<tr><td>${esc(t.service_name)}</td><td>${esc(t.quantity)}</td><td>${esc(t.unit)}</td></tr>`).join('');
 const details=d.details||{};
 $('#content').innerHTML=`<form id="report-period" class="inline-form"><div class="form-grid"><label>开始日期<input type="date" name="from" value="${from}" required></label><label>结束日期<input type="date" name="to" value="${to}" required></label></div><button class="secondary">查询同一期间</button></form><div class="metrics"><div class="metric"><strong>${d.encounterCount}</strong><span>实际就诊次数</span></div><div class="metric"><strong>${money(d.money.net)}</strong><span>现金净收（扣找零及历史退款）</span></div><div class="metric"><strong>${money(d.money.gross)}</strong><span>期间开单应收</span></div><div class="metric"><strong>${money(d.money.balance)}</strong><span>期间账单未结清</span></div></div><div class="panel"><h3>实际完成项目</h3>${rows?`<div class="table-wrap"><table><thead><tr><th>项目</th><th>实际数量</th><th>单位</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p>期间没有实际完成项目</p>'}</div><div class="panel"><h3>原始就诊依据</h3>${(details.encounters||[]).map(e=>`<p>${esc(e.encounter_no)} · ${timeStamp(e.started_at)} · ${esc(statusNames[e.status]||e.status)}</p>`).join('')||'<p>无</p>'}</div><div class="panel"><h3>项目完成明细</h3>${(details.treatments||[]).map(t=>`<p>${esc(t.encounter_no)} · ${esc(t.service_name)} × ${t.quantity} ${esc(t.unit)} · ${timeStamp(t.performed_at)}</p>`).join('')||'<p>无</p>'}</div><div class="panel"><h3>期间未结清账单依据</h3>${(details.unsettledInvoices||[]).map(i=>`<p>${esc(i.invoice_no)} · ${timeStamp(i.created_at)} · 应收 ${money(i.gross_amount)} · 未结清 ${money(i.balance)}</p>`).join('')||'<p>无</p>'}</div><div class="panel"><h3>现金结算凭据</h3>${(details.receipts||[]).map(c=>`<p>${esc(c.receipt_no)} · ${timeStamp(c.paid_at)} · 收到 ${money(c.tendered_amount)} − 找零 ${money(c.change_amount)} = 净收 ${money(c.due_amount)}</p>`).join('')||'<p>无</p>'}<details><summary>历史现金流水及退款</summary>${(details.payments||[]).map(x=>`<p>流水 ${x.id} · ${esc(x.reference_no||'历史收款')} · ${money(x.amount)} · ${timeStamp(x.paid_at)}</p>`).join('')}${(details.refunds||[]).map(x=>`<p>历史退款 ${x.id} · ${money(x.amount)} · ${timeStamp(x.processed_at)}</p>`).join('')}</details></div>`;
 $('#report-period').onsubmit=async ev=>{ev.preventDefault();const f=formData(ev.target);state.reportFrom=f.from;state.reportTo=f.to;try{await reports();}catch(e){flash(e.message,'error');}};
}

async function settings(){setHeader('负责人维护人员、资源与排班','系统设置');state.settings=await api('/api/admin/settings');const d=state.settings;const staff=`<div class="section-head"><div><h2>员工账号</h2><p>账号、岗位角色和启用状态</p></div><button class="primary" onclick="app.newStaff()">新增员工</button></div><div class="table-wrap"><table><thead><tr><th>员工</th><th>账号</th><th>角色</th><th>状态</th><th></th></tr></thead><tbody>${d.users.map(u=>`<tr><td><strong>${esc(u.display_name)}</strong></td><td>${esc(u.username)}</td><td>${String(u.roles).split(',').map(r=>esc(roleNames[r]||r)).join('、')}</td><td>${u.active?'启用':'停用'}</td><td><button class="ghost" onclick="app.editStaff(${u.id})">编辑</button></td></tr>`).join('')}</tbody></table></div>`;const chairs=`<div class="section-head"><div><h2>牙椅</h2><p>预约时使用的诊疗资源</p></div><button class="secondary" onclick="app.newChair()">新增牙椅</button></div><div class="table-wrap"><table><thead><tr><th>编码</th><th>名称</th><th>状态</th><th></th></tr></thead><tbody>${d.chairs.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.name)}</td><td>${c.active?'启用':'停用'}</td><td><button class="ghost" onclick="app.editChair(${c.id})">编辑</button></td></tr>`).join('')}</tbody></table></div>`;const services=`<div class="section-head"><div><h2>服务项目与价格</h2><p>新治疗使用当前价格，历史治疗保留原价格快照</p></div><button class="secondary" onclick="app.newService()">新增项目</button></div><div class="table-wrap"><table><thead><tr><th>编码</th><th>项目</th><th>时长</th><th class="amount">当前价格</th><th>状态</th><th></th></tr></thead><tbody>${d.services.map(s=>`<tr><td>${esc(s.code)}</td><td>${esc(s.name)}</td><td>${s.default_duration}分钟</td><td class="amount">${money(s.current_price)}</td><td>${s.active?'启用':'停用'}</td><td><button class="ghost" onclick="app.editService(${s.id})">编辑</button></td></tr>`).join('')}</tbody></table></div><div class="section-head"><div><h2>最近价格变更</h2><p>价格调整原因和操作人</p></div></div><div class="table-wrap"><table><thead><tr><th>时间</th><th>项目</th><th class="amount">价格</th><th>操作人</th><th>原因</th></tr></thead><tbody>${d.priceHistory.slice(0,20).map(h=>`<tr><td>${localDate(h.effective_from)} ${localTime(h.effective_from)}</td><td>${esc(h.service_code)} · ${esc(h.service_name)}</td><td class="amount">${money(h.price)}</td><td>${esc(h.changed_by_name||'系统')}</td><td>${esc(h.reason||'—')}</td></tr>`).join('')}</tbody></table></div>`;const days=['周日','周一','周二','周三','周四','周五','周六'];const hours=`<div class="section-head"><div><h2>诊所营业时间</h2><p>关闭日期不会生成预约时段</p></div></div><div class="table-wrap"><table><thead><tr><th>星期</th><th>营业时段</th><th>状态</th><th></th></tr></thead><tbody>${d.clinicHours.map(h=>`<tr><td>${days[h.weekday]}</td><td>${esc(h.open_time)}–${esc(h.close_time)}</td><td>${h.active?'营业':'休息'}</td><td><button class="ghost" onclick="app.editClinicHours(${h.weekday})">编辑</button></td></tr>`).join('')}</tbody></table></div>`;const schedules=`<div class="section-head"><div><h2>牙医每周排班</h2><p>排班必须位于诊所营业时间内</p></div><button class="secondary" onclick="app.newDentistSchedule()">设置班次</button></div><div class="table-wrap"><table><thead><tr><th>牙医</th><th>星期</th><th>班次</th><th>状态</th><th></th></tr></thead><tbody>${d.dentistSchedules.map(s=>`<tr><td>${esc(s.dentist_name)}</td><td>${days[s.weekday]}</td><td>${esc(s.start_time)}–${esc(s.end_time)}</td><td>${s.active?'上班':'停班'}</td><td><button class="ghost" onclick="app.editDentistSchedule(${s.dentist_id},${s.weekday})">编辑</button></td></tr>`).join('')}</tbody></table></div>`;const leaves=`<div class="section-head"><div><h2>员工请假</h2><p>已批准的牙医请假会自动占用相应预约时段</p></div><button class="secondary" onclick="app.newLeave()">登记请假</button></div><div class="table-wrap"><table><thead><tr><th>员工</th><th>开始</th><th>结束</th><th>原因</th><th>状态</th><th></th></tr></thead><tbody>${d.leaves.length?d.leaves.map(l=>`<tr><td>${esc(l.staff_name)}</td><td>${localDate(l.start_at)} ${localTime(l.start_at)}</td><td>${localDate(l.end_at)} ${localTime(l.end_at)}</td><td>${esc(l.reason)}</td><td>${l.status==='approved'?'已批准':'已取消'}</td><td>${l.status==='approved'?`<button class="ghost" onclick="app.cancelLeave(${l.id})">取消</button>`:''}</td></tr>`).join(''):`<tr><td colspan="6">暂无请假记录</td></tr>`}</tbody></table></div>`;const history=`<div class="panel"><h3>接诊安排变更历史</h3>${(d.scheduleHistory||[]).map(h=>{const old=h.old_json?JSON.parse(h.old_json):null,next=JSON.parse(h.new_json);return `<p>${timeStamp(h.changed_at)} · ${esc(h.changed_name)} · ${esc(h.reason)}<br>${esc(old?`${old.start_time}–${old.end_time}（${old.active?'上班':'停班'}）`:'原无安排')} → ${esc(next.start_time)}–${esc(next.end_time)}（${next.active?'上班':'停班'}）；确认意见：${esc(next.confirmation_note)}</p>`;}).join('')||'<p>尚无变更记录</p>'}</div>`;$('#content').innerHTML=staff+chairs+hours+schedules+history+leaves;}
function roleChecks(selected=[]){return ['manager','frontdesk','cashier','dentist','assistant'].map(r=>`<label class="check-row"><input type="checkbox" name="roles" value="${r}" ${selected.includes(r)?'checked':''}>${esc(roleNames[r])}</label>`).join('');}
function staffDialog(u){const edit=Boolean(u);modal(edit?'编辑员工':'新增员工',`<form id="staff-form"><div class="form-grid"><label>员工姓名 *<input name="displayName" value="${esc(u?.display_name||'')}" required></label><label>登录账号 *<input name="username" value="${esc(u?.username||'')}" ${edit?'readonly':''} required></label><fieldset class="full role-field"><legend>岗位角色 *</legend><div class="check-grid">${roleChecks(String(u?.roles||'').split(',').filter(Boolean))}</div></fieldset><label class="full">${edit?'新密码（不修改请留空）':'初始密码 *'}<input name="password" type="password" ${edit?'':'required'} minlength="8"></label>${edit?`<label>账号状态<select name="active"><option value="1" ${u.active?'selected':''}>启用</option><option value="0" ${u.active?'':'selected'}>停用</option></select></label>`:''}</div><div class="form-actions"><button class="primary">保存员工</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);b.roles=[...e.target.querySelectorAll('[name=roles]:checked')].map(x=>x.value);if(edit)b.active=b.active==='1';try{await api(edit?`/api/admin/users/${u.id}`:'/api/admin/users',{method:edit?'PUT':'POST',body:JSON.stringify(b)});closeModal();state.refs=await api('/api/reference');flash('员工账号已保存');settings();}catch(err){flash(err.message,'error');}});}
function newStaff(){staffDialog(null);}function editStaff(id){staffDialog(state.settings.users.find(x=>x.id===id));}
function chairDialog(c){const edit=Boolean(c);modal(edit?'编辑牙椅':'新增牙椅',`<form id="chair-form"><div class="form-grid"><label>牙椅编码 *<input name="code" value="${esc(c?.code||'')}" ${edit?'readonly':''} required></label><label>显示名称 *<input name="name" value="${esc(c?.name||'')}" required></label>${edit?`<label>状态<select name="active"><option value="1" ${c.active?'selected':''}>启用</option><option value="0" ${c.active?'':'selected'}>停用</option></select></label>`:''}</div><div class="form-actions"><button class="primary">保存牙椅</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);if(edit)b.active=b.active==='1';try{await api(edit?`/api/admin/chairs/${c.id}`:'/api/admin/chairs',{method:edit?'PUT':'POST',body:JSON.stringify(b)});closeModal();state.refs=await api('/api/reference');flash('牙椅资料已保存');settings();}catch(err){flash(err.message,'error');}});}
function newChair(){chairDialog(null);}function editChair(id){chairDialog(state.settings.chairs.find(x=>x.id===id));}
function serviceDialog(s){const edit=Boolean(s);modal(edit?'编辑诊疗项目':'新增诊疗项目',`<form><div class="form-grid"><label>项目编号<input name="code" value="${esc(s?.code||'')}" ${edit?'readonly':''} required></label><label>项目名称<input name="name" value="${esc(s?.name||'')}" required></label><label>计量单位<input name="unit" value="${esc(s?.unit||'项')}" required></label><label>预计时长（分钟）<input name="defaultDuration" type="number" min="1" step="1" value="${s?.default_duration||30}" required></label>${edit?`<label>状态<select name="active"><option value="1" ${s.active?'selected':''}>启用</option><option value="0" ${s.active?'':'selected'}>停用</option></select></label>`:''}</div><p>项目价格由收费人员依据负责人确认内容在价目页维护。</p><div class="form-actions"><button class="primary">保存项目资料</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);if(edit)b.active=b.active==='1';try{await api(edit?`/api/admin/services/${s.id}`:'/api/admin/services',{method:edit?'PUT':'POST',body:JSON.stringify(b)});closeModal();state.refs=await api('/api/reference');await settings();}catch(e){flash(e.message,'error');}});}
function newService(){serviceDialog(null);}function editService(id){serviceDialog(state.settings.services.find(x=>x.id===id));}

function editClinicHours(weekday){const h=state.settings.clinicHours.find(x=>x.weekday===weekday);const days=['周日','周一','周二','周三','周四','周五','周六'];modal(`编辑${days[weekday]}营业时间`,`<form><div class="form-grid"><label>开始<input name="openTime" type="time" value="${esc(h.open_time)}" required></label><label>结束<input name="closeTime" type="time" value="${esc(h.close_time)}" required></label><label>状态<select name="active"><option value="1" ${h.active?'selected':''}>营业</option><option value="0" ${h.active?'':'selected'}>休息</option></select></label></div><div class="form-actions"><button class="primary">保存</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);b.active=b.active==='1';try{await api(`/api/admin/clinic-hours/${weekday}`,{method:'PUT',body:JSON.stringify(b)});closeModal();flash('营业时间已保存');settings();}catch(err){flash(err.message,'error');}});}
function scheduleDialog(s){const dentists=state.settings.users.filter(u=>u.active&&String(u.roles).split(',').includes('dentist'));const days=['周日','周一','周二','周三','周四','周五','周六'];modal(s?'编辑牙医班次':'设置牙医班次',`<form><div class="form-grid"><label>牙医<select name="dentistId" ${s?'disabled':''}>${dentists.map(u=>`<option value="${u.id}" ${u.id===s?.dentist_id?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></label><label>星期<select name="weekday" ${s?'disabled':''}>${days.map((d,i)=>`<option value="${i}" ${i===s?.weekday?'selected':''}>${d}</option>`).join('')}</select></label><label>开始<input name="startTime" type="time" value="${esc(s?.start_time||'09:00')}" required></label><label>结束<input name="endTime" type="time" value="${esc(s?.end_time||'17:00')}" required></label><label>状态<select name="active"><option value="1" ${s?.active===0?'':'selected'}>上班</option><option value="0" ${s?.active===0?'selected':''}>停班</option></select></label><label class="full">安排／变更原因<textarea name="reason" required></textarea></label><label>牙医确认时间<input name="confirmedAt" type="datetime-local" value="${localInput()}" required></label><label class="full">牙医确认意见<textarea name="confirmationNote" required></textarea></label></div><div class="form-actions"><button class="primary">保存已确认安排</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);b.dentistId=s?.dentist_id||b.dentistId;b.weekday=s?.weekday??b.weekday;b.active=b.active==='1';b.expectedVersion=s?.version||0;b.confirmedBy=b.dentistId;b.confirmedAt=new Date(b.confirmedAt).toISOString();try{await api('/api/admin/dentist-schedules',{method:'POST',body:JSON.stringify(b)});closeModal();flash('牙医排班已保存');settings();}catch(err){flash(err.message,'error');}});}
function newDentistSchedule(){scheduleDialog(null);}function editDentistSchedule(dentistId,weekday){scheduleDialog(state.settings.dentistSchedules.find(x=>x.dentist_id===dentistId&&x.weekday===weekday));}
function newLeave(){const staff=state.settings.users.filter(u=>u.active);const now=new Date();now.setMinutes(now.getMinutes()-now.getTimezoneOffset());const start=now.toISOString().slice(0,16);const endDate=new Date(now.getTime()+3600000);const end=endDate.toISOString().slice(0,16);modal('登记员工请假',`<form><div class="form-grid"><label>员工<select name="userId">${staff.map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('')}</select></label><label>开始<input name="startAt" type="datetime-local" value="${start}" required></label><label>结束<input name="endAt" type="datetime-local" value="${end}" required></label><label class="full">原因<input name="reason" required placeholder="例如：参加培训"></label></div><div class="form-actions"><button class="primary">批准并登记</button></div></form>`,root=>root.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=formData(e.target);b.startAt=new Date(b.startAt).toISOString();b.endAt=new Date(b.endAt).toISOString();try{await api('/api/admin/leaves',{method:'POST',body:JSON.stringify(b)});closeModal();flash('请假已登记');settings();}catch(err){flash(err.message,'error');}});}
async function cancelLeave(id){try{await api(`/api/admin/leaves/${id}`,{method:'PUT',body:JSON.stringify({status:'cancelled'})});flash('请假记录已取消');settings();}catch(err){flash(err.message,'error');}}


const VIEW_ROLES={today:['frontdesk','dentist','assistant','manager'],patients:['frontdesk','cashier','dentist','assistant','manager'],appointments:['frontdesk','dentist','manager'],clinical:['dentist'],billing:['cashier','manager'],followups:['frontdesk','dentist','manager'],prices:['cashier','manager'],materials:['assistant','manager'],reconciliations:['cashier','manager'],reports:['cashier','manager'],settings:['manager']};
function defaultView(){return has('frontdesk','dentist','manager')?'today':has('cashier')?'billing':has('assistant')?'materials':'patients';}
function localInput(value){const x=value?new Date(value):new Date();return Number.isNaN(x.getTime())?'':new Date(x.getTime()-x.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function timeStamp(value){return value?`${localDate(value)} ${localTime(value)}`:'—';}
function managerOptions(){return state.refs.users.filter(u=>String(u.roles).split(',').includes('manager')).map(u=>`<option value="${u.id}">${esc(u.display_name)}</option>`).join('');}
function invoiceDue(i){return Number(i.receipt?.dueAmount??i.due_amount??i.dueAmount??i.gross_amount??0);}
function receiptHtml(r){return `<div class="panel receipt"><h3>现金结算收据</h3><p>收据号：${esc(r.receiptNo??r.receipt_no??'')}</p><p>应收：<strong>${money(r.dueAmount??r.due_amount)}</strong><br>实收现金：<strong>${money(r.tenderedAmount??r.tendered_amount)}</strong><br>找零：<strong>${money(r.changeAmount??r.change_amount)}</strong><br>收款时间：${esc(timeStamp(r.paidAt??r.paid_at))}</p></div>`;}
async function printReceipt(id){const printWindow=window.open('','_blank');if(!printWindow){flash('请允许打开收据打印窗口','error');return;}try{const {invoice:i}=await api(`/api/invoices/${id}`);if(!i.receipt)throw new Error('该次费用尚未结清');printWindow.document.write(`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>青禾牙科结算收据</title><body><h2>青禾牙科诊所</h2><p>${esc(i.full_name)} · ${esc(i.invoice_no)}</p>${receiptHtml(i.receipt)}<p>请核对收据与找零。</p></body></html>`);printWindow.document.close();printWindow.print();}catch(e){printWindow.close();flash(e.message,'error');}}
async function editAppointment(id){if(!has('frontdesk'))return;const a=state.appointments.find(x=>Number(x.id)===Number(id));if(!a||a.status!=='confirmed'){flash('仅可调整尚未到诊的已预约安排','error');return;}await appointmentDialog(a);}
async function appointmentDialog(a=null){
  const pd=await api('/api/patients');const dentists=state.refs.dentists;const service=state.refs.services.find(s=>Number(s.id)===Number(a?.service_id));const duration=a?Math.round((new Date(a.end_at)-new Date(a.start_at))/60000):(service?.default_duration||state.refs.services[0]?.default_duration||30);
  modal(a?'调整预约及接诊安排':'新增预约',`<form id="appointment-form"><div class="form-grid"><label class="full">患者<select name="patientId" ${a?'disabled':''} required><option value="">请选择患者</option>${pd.patients.map(p=>`<option value="${p.id}" ${Number(p.id)===Number(a?.patient_id)?'selected':''}>${esc(p.patient_no)} · ${esc(p.full_name)} · ${esc(p.phone||'')}</option>`).join('')}</select></label><label>接诊牙医<select name="dentistId" required>${dentists.map(u=>`<option value="${u.id}" ${Number(u.id)===Number(a?.dentist_id)?'selected':''}>${esc(u.display_name)}</option>`).join('')}</select></label><label>诊疗位置<select name="chairId" required>${state.refs.chairs.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(a?.chair_id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>预计诊疗项目<select name="serviceId" id="appt-service">${state.refs.services.map(s=>`<option value="${s.id}" data-duration="${s.default_duration}" ${Number(s.id)===Number(a?.service_id)?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>日期<input name="date" type="date" value="${a?isoDay(a.start_at):isoDay()}" required></label><label>预计时长（分钟）<input name="duration" type="number" min="10" step="5" value="${duration}" required></label><label>可用时段<select name="slot" required><option value="">正在读取…</option></select><span id="slot-help" class="subtext"></span></label><label class="full">候诊及接诊说明<input name="internalNote" value="${esc(a?.internal_note||'')}" required placeholder="如：到诊后在前台等候接诊"></label>${a?'<label class="full">调整原因<textarea name="reason" required></textarea></label>':''}<label class="full">负责人确认意见<textarea name="confirmationNote" required></textarea></label><label class="check-row full"><input name="confirmed" type="checkbox" required>已向所选接诊牙医核实安排，并与患者确认就诊时间</label></div><div class="form-actions"><button class="ghost" type="button" onclick="app.closeModal()">返回</button><button class="primary" id="appt-submit">保存已确认安排</button></div></form>`,root=>{
    const f=root.querySelector('form');const loadSlots=async()=>{const b=formData(f);const slot=f.querySelector('[name=slot]');const help=root.querySelector('#slot-help');slot.innerHTML='<option value="">正在读取…</option>';f.querySelector('#appt-submit').disabled=true;
      try{const q=new URLSearchParams({dentistId:b.dentistId,chairId:b.chairId,date:b.date,duration:b.duration});if(a)q.set('excludeId',a.id);const d=await api(`/api/availability?${q}`);const list=[...(d.slots||[])];
        if(a&&b.date===isoDay(a.start_at)&&Number(b.dentistId)===Number(a.dentist_id)&&Number(b.chairId)===Number(a.chair_id)&&Number(b.duration)===duration&&!list.some(x=>new Date(x.startAt).getTime()===new Date(a.start_at).getTime()))list.unshift({startAt:a.start_at,endAt:a.end_at,label:`${localTime(a.start_at)}–${localTime(a.end_at)}（原安排）`});
        slot.innerHTML=list.length?`<option value="">请选择时段</option>${list.map(x=>`<option value="${esc(x.startAt)}" data-end="${esc(x.endAt)}" ${a&&new Date(x.startAt).getTime()===new Date(a.start_at).getTime()?'selected':''}>${esc(x.label)}</option>`).join('')}`:'<option value="">没有可用时段</option>';help.textContent=d.reason||`可选择 ${list.length} 个时段`;f.querySelector('#appt-submit').disabled=!list.length;
      }catch(err){help.textContent=err.message;slot.innerHTML='<option value="">读取失败</option>';}
    };
    f.querySelector('#appt-service').onchange=ev=>{f.querySelector('[name=duration]').value=ev.target.selectedOptions[0].dataset.duration;loadSlots();};['dentistId','chairId','date','duration'].forEach(n=>f.querySelector(`[name=${n}]`).onchange=loadSlots);
    f.onsubmit=async ev=>{ev.preventDefault();const b=formData(f);const slot=f.querySelector('[name=slot]').selectedOptions[0];b.patientId=a?.patient_id||b.patientId;b.startAt=b.slot;b.endAt=slot?.dataset.end;b.status='confirmed';b.arrangementConfirmedBy=Number(b.dentistId);b.arrangementConfirmedAt=new Date().toISOString();if(a)b.expectedVersion=a.version;delete b.confirmed;delete b.slot;delete b.date;
      const button=f.querySelector('#appt-submit');button.disabled=true;try{await api(a?`/api/appointments/${a.id}`:'/api/appointments',{method:a?'PUT':'POST',body:JSON.stringify(b)});closeModal();flash(a?'预约安排已更新并保留变更原因':'预约与接诊安排已保存');await navigate(state.view);}catch(err){flash(err.message,'error');await loadSlots();}
    };loadSlots();
  });
}
async function prices(){setHeader('负责人确认，收费人员维护','收费价目',has('cashier')?'<button class="primary" onclick="app.newPrice()">维护价目版本</button>':'');const first=state.priceServiceId||state.refs.services[0]?.id;$('#content').innerHTML=`<div class="inline-form"><div class="form-grid"><label>收费项目<select id="price-service" onchange="app.loadPrices(this.value)">${state.refs.services.map(s=>`<option value="${s.id}" ${Number(first)===Number(s.id)?'selected':''}>${esc(s.name)} · ${esc(s.unit||'次')}</option>`).join('')}</select></label></div></div><div id="price-list"></div>`;if(first)await loadPrices(first);else $('#price-list').innerHTML=empty('尚无收费项目','请由负责人确认项目资料。');}
async function loadPrices(serviceId){state.priceServiceId=Number(serviceId);const d=await api(`/api/price-versions?serviceId=${encodeURIComponent(serviceId)}`);const rows=d.versions||[];state.priceVersions=rows;$('#price-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>项目</th><th class="amount">单价</th><th>适用区间</th><th>负责人确认</th><th>依据</th><th>维护</th></tr></thead><tbody>${rows.map(v=>`<tr><td>${esc(v.service_name)}</td><td class="amount">${money(v.unit_price)}</td><td>${timeStamp(v.effective_from)}<span class="subtext">至 ${v.effective_to?timeStamp(v.effective_to):'未指定结束时间'}</span></td><td>${esc(v.confirmed_name)}<span class="subtext">${timeStamp(v.confirmed_at)}</span></td><td>${esc(v.confirmation_note||'')}</td><td>${has('cashier')?`<button class="ghost" onclick="app.endPrice(${v.id})">结束适用</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('尚无适用价目','收费人员依据负责人确认的价格维护。');}
function newPrice(){if(!has('cashier'))return;modal('维护负责人已确认的价目',`<form><div class="form-grid"><label>收费项目<select name="serviceId">${state.refs.services.filter(s=>Number(s.id)===Number(state.priceServiceId)).map(s=>`<option value="${s.id}" ${Number(s.id)===state.priceServiceId?'selected':''}>${esc(s.name)} · ${esc(s.unit||'次')}</option>`).join('')}</select></label><label>同时结束旧价目<select name="replacesVersionId"><option value="">不调整旧区间</option>${(state.priceVersions||[]).map(v=>`<option value="${v.id}">${money(v.unit_price)} · ${timeStamp(v.effective_from)}</option>`).join('')}</select></label><label>单价<input name="unitPrice" type="number" min="0" step="0.01" required></label><label>适用开始<input name="effectiveFrom" type="datetime-local" value="${localInput()}" required></label><label>适用结束<input name="effectiveTo" type="datetime-local"></label><label>确认负责人<select name="confirmedBy" required>${managerOptions()}</select></label><label>负责人确认时间<input name="confirmedAt" type="datetime-local" value="${localInput()}" required></label><label class="full">调整原因及确认依据<textarea name="confirmationNote" required></textarea></label><label class="check-row full"><input type="checkbox" name="confirmed" required>以上价目内容已经负责人确认</label></div><p class="subtext">适用区间包含开始、不包含结束；新版本不可覆盖既往费用依据。</p><div class="form-actions"><button class="primary">保存价目</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);b.effectiveFrom=new Date(b.effectiveFrom).toISOString();b.confirmedAt=new Date(b.confirmedAt).toISOString();if(b.effectiveTo)b.effectiveTo=new Date(b.effectiveTo).toISOString();else delete b.effectiveTo;delete b.confirmed;if(b.replacesVersionId){const old=state.priceVersions.find(v=>Number(v.id)===Number(b.replacesVersionId));b.expectedVersion=old?.version;}else delete b.replacesVersionId;try{await api('/api/price-versions',{method:'POST',body:JSON.stringify(b)});state.priceServiceId=Number(b.serviceId);state.refs=await api('/api/reference');closeModal();flash('价目版本已保存');await navigate('prices');}catch(err){flash(err.message,'error');}});}
async function materials(){setHeader('核对实物，记录每次库存变动','材料管理',has('assistant')?'<button class="primary" onclick="app.newMaterial()">登记材料</button>':'');const d=await api(`/api/materials?${new URLSearchParams(state.materialQuery||{})}`);state.materials=d.items||[];const rows=state.materials.map(m=>`<tr><td>${esc(m.code)} · ${esc(m.name)}<span class="subtext">查询编号：${m.id}</span></td><td>${esc(m.unit)}</td><td>${esc(m.stock_quantity)}</td><td class="row-actions">${has('assistant')?`<button class="secondary" onclick="app.materialMovement(${m.id},'inbound')">入库</button><button class="ghost" onclick="app.materialMovement(${m.id},'issue')">领用</button><button class="ghost" onclick="app.materialMovement(${m.id},'adjustment')">盘点调整</button>`:'仅查询'}</td></tr>`).join('');const names={inbound:'入库',issue:'领用',adjustment:'盘点调整'};const history=(d.movements||[]).map(m=>`<tr><td>${esc(m.material_name)}</td><td>${esc(names[m.type]||m.type)}</td><td>${esc(m.before_quantity)} → ${esc(m.after_quantity)}</td><td>${esc(m.reason)}</td><td>${esc(m.actor_name)}<span class="subtext">${timeStamp(m.created_at)}${m.confirmed_name?' · 确认：'+esc(m.confirmed_name):''}</span></td></tr>`).join('');$('#content').innerHTML=`<form id="material-query" class="inline-form"><div class="form-grid"><label>材料编号<input name="materialId" type="number" min="1" value="${esc(state.materialQuery?.materialId||'')}" placeholder="留空查询全部"></label><label>开始日期<input name="from" type="date" value="${esc(state.materialQuery?.from||'')}"></label><label>结束日期<input name="to" type="date" value="${esc(state.materialQuery?.to||'')}"></label></div><button class="secondary">查询材料及流水</button></form><p class="subtext">库存为当前余额；流水按材料及期间筛选，日期留空显示全部原始记录。</p>${rows?`<div class="table-wrap"><table><thead><tr><th>材料</th><th>计量单位</th><th>账面库存</th><th>实际办理</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('尚无材料','先登记材料名称和计量单位。')}${history?`<div class="section-head"><h2>库存变动台账</h2></div><div class="table-wrap"><table><thead><tr><th>材料</th><th>类型</th><th>变动前后数量</th><th>用途／原因</th><th>经办及确认</th></tr></thead><tbody>${history}</tbody></table></div>`:''}`;$('#material-query').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);delete b.requestId;state.materialQuery=Object.fromEntries(Object.entries(b).filter(([k,v])=>v));try{await materials();}catch(e){flash(e.message,'error');}};}
function newMaterial(){modal('登记材料资料',`<form><div class="form-grid"><label>材料编号<input name="code" required></label><label>材料名称<input name="name" required></label><label>计量单位<input name="unit" required placeholder="如：盒、支"></label></div><div class="form-actions"><button class="primary">保存材料资料</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await api('/api/materials',{method:'POST',body:JSON.stringify(formData(ev.target))});closeModal();flash('材料资料已登记');await navigate('materials');}catch(err){flash(err.message,'error');}});}
function materialMovement(id,type){const m=state.materials.find(x=>Number(x.id)===Number(id));if(!m)return;const names={inbound:'材料入库',issue:'材料领用',adjustment:'材料盘点调整'};const adjust=type==='adjustment';modal(names[type],`<form><p>${esc(m.name)} · ${esc(m.unit)}，当前账面数量：${esc(m.stock_quantity)}</p><div class="form-grid"><label>${adjust?'实际盘点数量':'本次'+(type==='issue'?'领用':'入库')+'数量'}<input name="${adjust?'countedQuantity':'quantity'}" type="number" min="${adjust?'0':'0.001'}" step="any" ${type==='issue'?`max="${Number(m.stock_quantity)}"`:''} required></label><label class="full">${adjust?'差异原因及核实情况':'实际用途／收发依据'}<textarea name="reason" required></textarea></label>${adjust?`<label>确认负责人<select name="confirmedBy" required>${managerOptions()}</select></label><label>确认时间<input name="confirmedAt" type="datetime-local" value="${localInput()}" required></label><label class="full">负责人确认意见<textarea name="confirmationNote" required></textarea></label><label class="check-row full"><input name="confirmed" type="checkbox" required>盘点差异和调整内容已由负责人确认</label>`:''}<label class="check-row full"><input type="checkbox" name="checked" required>已核对本次材料及实际数量</label></div><div class="form-actions"><button class="primary">登记${adjust?'已确认调整':'实际库存变动'}</button></div></form>`,root=>root.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const b=formData(ev.target);b.type=type;b.expectedVersion=m.version;if(b.confirmedAt)b.confirmedAt=new Date(b.confirmedAt).toISOString();delete b.confirmed;delete b.checked;try{await api(`/api/materials/${id}/movements`,{method:'POST',body:JSON.stringify(b)});closeModal();flash('库存变动及办理依据已保存');await navigate('materials');}catch(err){flash(err.message,'error');}});}
async function reconciliations(){const day=state.reconciliationDay||isoDay();setHeader('核对实际现金净收与有效结算','日常业务与收款核对',has('cashier')?'<button class="primary" onclick="app.newReconciliation()">登记现金核对</button>':'');$('#content').innerHTML=`<div class="inline-form"><div class="form-grid"><label>核对日期<input id="reconciliation-date" type="date" value="${day}" onchange="app.loadReconciliations(this.value)"></label></div></div><div id="reconciliation-content"></div>`;await loadReconciliations(day);}
async function loadReconciliations(day){state.reconciliationDay=day;const d=await api(`/api/reconciliations?date=${day}`);state.reconciliationSummary=d.summary;const x=d.summary||{};const rows=(d.records||[]).map(r=>`<tr><td>${esc(r.date)}</td><td class="amount">${money(r.expected_cash)}</td><td class="amount">${money(r.counted_cash)}</td><td class="amount ${Number(r.difference)!==0?'risk':''}">${money(r.difference)}</td><td>${esc(r.difference_reason||'一致')}<span class="subtext">${esc(r.resolution_note||'')}${r.confirmed_name?' · '+esc(r.confirmed_name)+' '+timeStamp(r.confirmed_at)+' · '+esc(r.confirmation_note):''}</span></td><td>${esc(r.recorded_name)}<span class="subtext">${timeStamp(r.created_at)}</span></td></tr>`).join('');$('#reconciliation-content').innerHTML=`<div class="metrics"><div class="metric"><strong>${Number(x.encounterCount||0)}</strong><span>当日就诊次数</span></div><div class="metric"><strong>${Number(x.invoiceCount||0)}</strong><span>结算依据数</span></div><div class="metric"><strong>${money(x.expectedCash)}</strong><span>有效现金净收</span></div><div class="metric"><strong>${money(x.unsettledAmount)}</strong><span>尚未结清金额</span></div></div><div class="panel"><h3>本次查询的收款依据</h3>${(x.basis?.receipts||[]).map(c=>`<p>${esc(c.receipt_no)} · 收到 ${money(c.tendered_amount)} − 找零 ${money(c.change_amount)} = ${money(c.due_amount)}</p>`).join('')||'<p>无当日结算收据</p>'}${(x.basis?.legacyPayments||[]).map(c=>`<p>历史收款流水 ${c.id} · ${money(c.amount)}</p>`).join('')}${(x.basis?.refunds||[]).map(c=>`<p>历史退款流水 ${c.id} · −${money(c.amount)}</p>`).join('')}</div>${rows?`<div class="table-wrap"><table><thead><tr><th>日期</th><th class="amount">账面净收</th><th class="amount">实点净收</th><th class="amount">差额</th><th>核实及处理意见</th><th>收费经办</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('当天尚无现金核对登记','收费人员核对现金及原始凭据后登记。')}`;}
function newReconciliation(){if(!has('cashier'))return;const day=state.reconciliationDay||isoDay();const expected=Number(state.reconciliationSummary?.expectedCash||0);modal('登记当日现金核对',`<form><p>核对日期：${esc(day)}；有效现金净收：${money(expected)}</p><div class="form-grid"><label>实点现金净收<input name="countedCash" type="number" min="0" step="0.01" value="${expected}" required></label><label>差额<input id="cash-difference" value="${money(0)}" readonly></label><label class="full">差异原因及复核情况<textarea name="differenceReason" placeholder="有差额时须复核现金和原始收据并说明"></textarea></label><label class="full">负责人处理意见／后续安排<textarea name="resolutionNote"></textarea></label><label>差异确认负责人<select name="confirmedBy">${managerOptions()}</select></label><label>差异确认时间<input name="confirmedAt" type="datetime-local" value="${localInput()}"></label><label class="full">差异确认意见<textarea name="confirmationNote"></textarea></label><label class="check-row full"><input type="checkbox" required>已核对现金、开班现金及当日收款凭据</label></div><p class="subtext">填写扣除开班现金后的当日实点净收；核对说明不会改写已结清收据。</p><div class="form-actions"><button class="primary">保存核对结果</button></div></form>`,root=>{const f=root.querySelector('form');f.querySelector('[name=countedCash]').oninput=ev=>{root.querySelector('#cash-difference').value=money(Number(ev.target.value)-expected);};f.onsubmit=async ev=>{ev.preventDefault();const b=formData(f);b.date=day;b.basisHash=state.reconciliationSummary.basisHash;if(b.confirmedAt)b.confirmedAt=new Date(b.confirmedAt).toISOString();if(Math.abs(Number(b.countedCash)-expected)>0.005&&(!b.differenceReason.trim()||!b.resolutionNote.trim())){flash('存在差额时请填写原因及负责人处理意见','error');return;}try{await api('/api/reconciliations',{method:'POST',body:JSON.stringify(b)});closeModal();flash('日常核对结果已保存');await navigate('reconciliations');}catch(err){flash(err.message,'error');}};});}

window.app={navigate,availabilityDialog,searchAppointments,exportDialog,newPatient,editPatient,planDecision,searchPatients,patientDetail,newAppointment,editAppointment,loadAppointments,apptStatus,openAppointmentEncounter,encounterDetail,uploadAttachment,openAttachment,archiveAttachment,signEncounter,amendEncounter,addPlan,addTreatment,createInvoice,invoiceDetail,printReceipt,newFollowup,followupDetail,newPrice,loadPrices,endPrice,correctProjects,newMaterial,materialMovement,newReconciliation,loadReconciliations,newStaff,editStaff,newService,editService,newChair,editChair,editClinicHours,newDentistSchedule,editDentistSchedule,newLeave,cancelLeave,closeModal};

(async()=>{try{const d=await api('/api/me');state.user=d.user;state.csrf=d.csrf;state.refs=await api('/api/reference');showApp();navigate(defaultView());}catch{showLogin();}})();
